<?php
require __DIR__.'/../includes/new-common.php';$id=(int)($_GET['id']??0);$rate=eco_rate();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();try{
  $action=$_POST['action']??'save';if($action==='delete_list'&&$id){$s=$pdo->prepare('DELETE FROM eco_lists WHERE id=?');$s->execute([$id]);redirect('/lists/');}
  if($action==='delete_product'&&$id){$s=$pdo->prepare('DELETE FROM eco_list_products WHERE id=? AND list_id=?');$s->execute([(int)$_POST['product_id'],$id]);redirect('/lists/edit.php?id='.$id);}
  if($action==='save_list'){$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException('Introdu numele listei.');if($id){$s=$pdo->prepare('UPDATE eco_lists SET name=?,description=? WHERE id=?');$s->execute([$name,$_POST['description']??'',$id]);}else{$s=$pdo->prepare('INSERT INTO eco_lists(name,description) VALUES (?,?)');$s->execute([$name,$_POST['description']??'']);$id=(int)$pdo->lastInsertId();}redirect('/lists/edit.php?id='.$id);}
  if($action==='save_product'&&$id){
   $name=trim($_POST['product_name']??'');if(!$name)throw new RuntimeException('Introdu denumirea produsului.');
   $eur=(float)str_replace(',','.',$_POST['price_eur']??'0');if($eur<0)throw new RuntimeException('Preț invalid.');
   $tierMode=isset($_POST['tier_mode']);$tiers=$tierMode?eco_parse_tiers($_POST['tiers']??[]):[];if($tierMode&&!$tiers)throw new RuntimeException('Adaugă cel puțin un prag de cantitate.');if(!$tierMode)$tiers=[];
   if($tiers)$eur=$tiers[0]['price'];
   $r=(float)($rate['rate']??0);if(!$r){$r=(float)str_replace(',','.',(string)($_POST['manual_rate']??0));if($r<3||$r>8)throw new RuntimeException('Cursul automat este indisponibil. Introdu un curs EUR/RON verificat (între 3 și 8).');}
   $pid=(int)($_POST['product_id']??0);$values=[trim($_POST['reference']??''),$name,$eur,round($eur*$r,2),$r,isset($_POST['on_site'])?1:0,($_POST['checked_at']??'')?:null,trim($_POST['notes']??'')];
   $pdo->beginTransaction();
   if($pid){$s=$pdo->prepare('UPDATE eco_list_products SET reference=?,name=?,price_eur=?,price_ron=?,exchange_rate=?,on_site=?,checked_at=?,notes=? WHERE id=? AND list_id=?');$s->execute([...$values,$pid,$id]);if(!$s->rowCount()){$s=$pdo->prepare('SELECT id FROM eco_list_products WHERE id=? AND list_id=?');$s->execute([$pid,$id]);if(!$s->fetch())throw new RuntimeException('Produsul nu aparține listei.');}}
   else{$s=$pdo->prepare('INSERT INTO eco_list_products(reference,name,price_eur,price_ron,exchange_rate,on_site,checked_at,notes,list_id) VALUES (?,?,?,?,?,?,?,?,?)');$s->execute([...$values,$id]);$pid=(int)$pdo->lastInsertId();}
   eco_save_tiers($pdo,$pid,$tiers);$pdo->commit();redirect('/lists/edit.php?id='.$id);
  }

 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();error_log('[ECOsoft list save] '.$e->getMessage());}}
$list=null;$products=[];if($id){$s=$pdo->prepare('SELECT * FROM eco_lists WHERE id=?');$s->execute([$id]);$list=$s->fetch();if(!$list){http_response_code(404);exit('Lista nu există.');}$s=$pdo->prepare('SELECT * FROM eco_list_products WHERE list_id=? ORDER BY id DESC');$s->execute([$id]);$products=$s->fetchAll();}
$tiersMap=eco_tiers_map($pdo,$products);$editing=null;if($id&&!empty($_GET['product'])){foreach($products as $p){if((int)$p['id']===(int)$_GET['product'])$editing=$p;}}
$editTiers=$editing?($tiersMap[(int)$editing['id']]??[]):[];
if($error!==''&&($_POST['action']??'')==='save_product'){
 $editing=array_merge($editing??[],['id'=>(int)($_POST['product_id']??0),'reference'=>(string)($_POST['reference']??''),'name'=>(string)($_POST['product_name']??''),'price_eur'=>(string)($_POST['price_eur']??''),'checked_at'=>(string)($_POST['checked_at']??''),'notes'=>(string)($_POST['notes']??''),'on_site'=>isset($_POST['on_site'])?1:0]);
 $editTiers=[];if(isset($_POST['tier_mode']))foreach(($_POST['tiers']??[]) as $t){$editTiers[]=['min_qty'=>$t['min']??'','max_qty'=>$t['max']??'','price_eur'=>$t['price']??''];}
}
require __DIR__.'/../includes/header.php';?>
<div class="eco-heading"><div><a class="eco-back" href="/lists/">← Toate listele</a><h1><?=e($list['name']??'Listă nouă')?></h1><p>Editor pentru adăugarea produselor și administrarea listei.</p></div></div><?php if($error):?><div class="eco-error" id="ecoSaveError" role="alert"><strong>Produsul nu a fost salvat:</strong> <?=e($error)?></div><?php endif;?>
<form method="post" class="eco-panel"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save_list"><h2>Detalii listă</h2><div class="eco-form-grid"><label>Nume listă<input name="name" required value="<?=e($list['name']??'')?>" placeholder="Ex. Produse marca MICROHARD"></label><label>Descriere opțională<input name="description" value="<?=e($list['description']??'')?>" placeholder="Detalii despre această listă"></label></div><button class="eco-button">Salvează lista</button></form>
<?php if($id):?><div class="eco-heading"><a class="eco-button" href="/lists/bulk.php?id=<?=$id?>">Actualizare rapidă în tabel →</a></div><div class="eco-heading"><a class="eco-button eco-button-light" target="_blank" href="/lists/pdf.php?id=<?=$id?>">Export PDF listă ↗</a></div><div class="eco-heading"><div><h2>Produse în listă (<?=count($products)?>)</h2></div></div><div class="eco-table-scroll"><table class="eco-table"><thead><tr><th>Referință / Produs</th><th>EUR</th><th>RON</th><th>Pe site</th><th>Actualizat</th><th>Observații</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><small><?=e($p['reference'])?></small><br><strong><?=e($p['name'])?></strong></td><td><?php if(!empty($tiersMap[$p['id']])):?><?php foreach($tiersMap[$p['id']] as $t):?><div class="eco-tier-line"><small><?=e(eco_tier_label($t))?></small><strong><?=eco_money($t['price_eur'])?>/buc.</strong></div><?php endforeach;?><?php else:?><?=eco_money($p['price_eur'])?><?php endif;?></td><td><?php if(!empty($tiersMap[$p['id']])):?><?php foreach($tiersMap[$p['id']] as $t):?><div class="eco-tier-line"><?=eco_money((float)$t['price_eur']*(float)$p['exchange_rate'],'RON')?>/buc.</div><?php endforeach;?><?php else:?><?=eco_money($p['price_ron'],'RON')?><?php endif;?></td><td><?=$p['on_site']?'Da':'Nu'?></td><td><?=e($p['checked_at']??'—')?></td><td><?=e($p['notes']??'')?></td><td><a class="eco-text-link" href="?id=<?=$id?>&product=<?=$p['id']?>#product-editor">Editează</a><form method="post" class="eco-inline" onsubmit="return confirm('Ștergi produsul?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete_product"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="eco-link-danger">Șterge</button></form></td></tr><?php endforeach;?></tbody></table></div>
<form method="post" id="product-editor" class="eco-panel"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="product_id" value="<?=(int)($editing['id']??0)?>"><h2><?=$editing?'Editează produsul':'Adaugă produs'?></h2><div class="eco-form-grid"><label>Referință<input name="reference" value="<?=e($editing['reference']??'')?>"></label><label>Denumire produs<input name="product_name" required value="<?=e($editing['name']??'')?>"></label><label>Preț EUR<input id="ecoEur" type="number" min="0" step="0.01" name="price_eur" value="<?=e((string)($editing['price_eur']??''))?>"></label><div class="eco-full eco-tier-box"><label class="eco-check"><input type="checkbox" id="tierMode" name="tier_mode" value="1" <?=!empty($editTiers)?'checked':''?>> Prețuri pe cantități (tiered pricing)</label><p class="eco-muted">Exemplu fără suprapuneri: 100 buc. → 4,50 €, 101–500 buc. → 2,80 €, 2.000+ buc. → 2,00 €. Introdu fiecare interval explicit. Lasă „Până la” gol pentru un prag fără limită superioară (ex. 2.000+).</p><div id="tierRows"><?php foreach($editTiers as $i=>$t):?><div class="eco-tier-row"><label>De la (buc.)<input type="number" min="1" name="tiers[<?=$i?>][min]" value="<?=e((string)$t['min_qty'])?>"></label><label>Până la (opțional)<input type="number" min="1" name="tiers[<?=$i?>][max]" value="<?=e((string)$t['max_qty'])?>"></label><label>EUR/buc.<input type="text" inputmode="decimal" name="tiers[<?=$i?>][price]" value="<?=e((string)$t['price_eur'])?>"></label><button type="button" class="eco-button eco-button-light eco-remove-tier">×</button></div><?php endforeach;?></div><button type="button" class="eco-button eco-button-light" id="addTier">+ Adaugă prag</button></div><label>Curs manual EUR/RON (doar dacă sursele online nu funcționează)<input id="ecoManualRate" name="manual_rate" type="number" min="3" max="8" step="0.0001" placeholder="Ex. 5.0000"></label><label>Preț RON · calcul automat<input id="ecoRon" readonly value=""></label><label>Data actualizării (opțional)<input type="date" name="checked_at" value="<?=e($editing['checked_at']??'')?>"></label><label class="eco-check"><input type="checkbox" name="on_site" <?=!empty($editing['on_site'])?'checked':''?>> Disponibil pe site</label><label class="eco-full">Observații<textarea name="notes" rows="3"><?=e($editing['notes']??'')?></textarea></label></div><p class="eco-muted">Curs EUR/RON (<?=e($rate['source']??'')?><?=!empty($rate['stale'])?' · ultimul curs salvat':''?>): <?=$rate['rate']?number_format($rate['rate'],4,',','.').' RON':'indisponibil'?> · <?=e($rate['date']??'—')?>. Valoarea RON este salvată la cursul din momentul editării.</p><button class="eco-button">Salvează produsul</button><?php if($editing):?><a class="eco-button eco-button-light" href="?id=<?=$id?>#product-editor">Anulează editarea</a><?php endif;?></form>
