<script>const eur=document.getElementById('ecoEur'),ron=document.getElementById('ecoRon'),rate=<?=json_encode($rate['rate']??0)?>;function calc(){const effectiveRate=rate||Number(document.getElementById('ecoManualRate').value||0);ron.value=effectiveRate?(Number(eur.value||0)*effectiveRate).toLocaleString('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2})+' RON':'Curs indisponibil'}eur.addEventListener('input',calc);document.getElementById('ecoManualRate').addEventListener('input',calc);calc();</script>
<script>(()=>{const toggle=document.getElementById('tierMode'),rows=document.getElementById('tierRows'),add=document.getElementById('addTier'),price=document.getElementById('ecoEur');let n=rows.children.length;function sync(){rows.parentElement.classList.toggle('eco-tier-active',toggle.checked);price.readOnly=toggle.checked;price.required=!toggle.checked;price.style.opacity=toggle.checked?'.5':'1';rows.querySelectorAll('input').forEach(x=>x.disabled=!toggle.checked);}function addRow(){const i=n++;const d=document.createElement('div');d.className='eco-tier-row';d.innerHTML=`<label>De la (buc.)<input type="number" min="1" name="tiers[${i}][min]"></label><label>Până la (opțional)<input type="number" min="1" name="tiers[${i}][max]"></label><label>EUR/buc.<input type="text" inputmode="decimal" name="tiers[${i}][price]"></label><button type="button" class="eco-button eco-button-light eco-remove-tier">×</button>`;rows.appendChild(d);sync();}add.onclick=addRow;toggle.onchange=()=>{if(toggle.checked&&!rows.children.length)addRow();sync();};rows.addEventListener('click',e=>{if(e.target.closest('.eco-remove-tier')){e.target.closest('.eco-tier-row').remove();sync();}});sync();})();</script>
